begin;
grant vida_identity_owner to postgres with inherit true, set true;
grant create on schema public to vida_identity_owner;

do $preflight$ begin if to_regclass('public.client_account_membership_events') is null or to_regprocedure('public.remove_client_account_membership(uuid,uuid,text)') is null or to_regprocedure('public.grant_client_account_authorization(uuid,uuid,text,text,uuid,uuid)') is null then raise exception 'M4 ABORTADA: membership governance / authorization RPCs ausentes';end if;if to_regclass('public.client_account_offboarding_workflows') is not null or to_regclass('public.client_account_offboarding_events') is not null then raise exception 'M4 ABORTADA: objetos de offboarding já existem';end if;end;$preflight$;

create table public.client_account_offboarding_workflows(id uuid primary key default gen_random_uuid(),client_account_id uuid not null references public.client_accounts(id) on delete restrict,target_auth_user_id uuid not null,requested_by_auth_user_id uuid not null,replacement_owner_auth_user_id uuid,justification text not null check(btrim(justification)<>''),state text not null check(state in ('requested','database_access_removed','sessions_revoked','completed')),retry_count integer not null default 0 check(retry_count>=0),last_error_stage text check(last_error_stage is null or last_error_stage in ('revoke_sessions','delete_user')),last_error_code text,requested_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),completed_at timestamptz,constraint offboarding_completed_at_matches_state check((state='completed' and completed_at is not null) or (state<>'completed' and completed_at is null)),constraint offboarding_target_not_replacement check(replacement_owner_auth_user_id is null or replacement_owner_auth_user_id<>target_auth_user_id),unique(client_account_id,target_auth_user_id));
create table public.client_account_offboarding_events(id uuid primary key default gen_random_uuid(),workflow_id uuid not null references public.client_account_offboarding_workflows(id) on delete restrict,event_type text not null check(event_type in ('requested','replacement_owner_established','database_access_removed','sessions_revoked','retryable_failure','completed')),actor_type text not null check(actor_type in ('authenticated','backend_system')),actor_auth_user_id uuid,stage text,detail_code text,occurred_at timestamptz not null default clock_timestamp(),constraint offboarding_event_actor_matches_type check((actor_type='authenticated' and actor_auth_user_id is not null) or (actor_type='backend_system' and actor_auth_user_id is null)));
alter table public.client_account_offboarding_workflows enable row level security;alter table public.client_account_offboarding_events enable row level security;revoke all on table public.client_account_offboarding_workflows,public.client_account_offboarding_events from public,anon,authenticated,service_role;grant select on table public.client_account_offboarding_workflows to service_role;grant select on table public.client_account_offboarding_events to service_role;
create trigger client_account_offboarding_events_forbid_update before update on public.client_account_offboarding_events for each row execute function vida_internal.forbid_update_delete();create trigger client_account_offboarding_events_forbid_delete before delete on public.client_account_offboarding_events for each row execute function vida_internal.forbid_update_delete();

create function public.start_client_account_offboarding(p_client_account_id uuid,p_target_auth_user_id uuid,p_replacement_owner_auth_user_id uuid,p_justification text) returns uuid language plpgsql security definer set search_path='' as $$ declare v_actor uuid:=vida_internal.current_auth_uid();v_workflow public.client_account_offboarding_workflows;v_target_is_owner boolean;v_other_owner_exists boolean;v_replacement_is_owner boolean;begin if v_actor is null then raise exception 'start_client_account_offboarding exige sessão autenticada';end if;if p_client_account_id is null or p_target_auth_user_id is null then raise exception 'client_account_id e target_auth_user_id são obrigatórios';end if;if p_justification is null or btrim(p_justification)='' then raise exception 'justification é obrigatória e não pode ser vazia';end if;perform 1 from public.client_accounts where id=p_client_account_id for update;if not found then raise exception 'client_account % inexistente',p_client_account_id;end if;if not vida_internal.has_role_in_scope(p_client_account_id,array['planner_owner']) then raise exception 'usuário % não é planner_owner desta conta — não pode iniciar offboarding',v_actor;end if;select * into v_workflow from public.client_account_offboarding_workflows where client_account_id=p_client_account_id and target_auth_user_id=p_target_auth_user_id;if found then if v_workflow.replacement_owner_auth_user_id is distinct from p_replacement_owner_auth_user_id or v_workflow.justification is distinct from btrim(p_justification) then raise exception 'offboarding já existe para esta conta/usuário com parâmetros diferentes';end if;return v_workflow.id;end if;if not exists(select 1 from public.client_account_users where client_account_id=p_client_account_id and auth_user_id=p_target_auth_user_id) then raise exception 'target_auth_user_id % não possui membership ativo nesta conta',p_target_auth_user_id;end if;select exists(select 1 from public.client_account_user_authorizations where client_account_id=p_client_account_id and auth_user_id=p_target_auth_user_id and role='planner_owner' and scope_type='account' and revoked_at is null) into v_target_is_owner;select exists(select 1 from public.client_account_user_authorizations where client_account_id=p_client_account_id and auth_user_id is distinct from p_target_auth_user_id and role='planner_owner' and scope_type='account' and revoked_at is null) into v_other_owner_exists;if not v_target_is_owner and p_replacement_owner_auth_user_id is not null then raise exception 'replacement_owner_auth_user_id só se aplica quando o usuário alvo é planner_owner';end if;if v_target_is_owner and v_other_owner_exists and p_replacement_owner_auth_user_id is not null then if not exists(select 1 from public.client_account_user_authorizations where client_account_id=p_client_account_id and auth_user_id=p_replacement_owner_auth_user_id and role='planner_owner' and scope_type='account' and revoked_at is null) then raise exception 'replacement_owner_auth_user_id informado não é planner_owner ativo desta conta';end if;end if;if v_target_is_owner and not v_other_owner_exists then if p_replacement_owner_auth_user_id is null then raise exception 'offboarding do último planner_owner exige replacement_owner_auth_user_id';end if;if not exists(select 1 from public.client_account_users where client_account_id=p_client_account_id and auth_user_id=p_replacement_owner_auth_user_id) then raise exception 'replacement_owner_auth_user_id % não possui membership ativo nesta conta',p_replacement_owner_auth_user_id;end if;select exists(select 1 from public.client_account_user_authorizations where client_account_id=p_client_account_id and auth_user_id=p_replacement_owner_auth_user_id and role='planner_owner' and scope_type='account' and revoked_at is null) into v_replacement_is_owner;if not v_replacement_is_owner then perform public.grant_client_account_authorization(p_client_account_id,p_replacement_owner_auth_user_id,'planner_owner','account',null,null);end if;end if;insert into public.client_account_offboarding_workflows(client_account_id,target_auth_user_id,requested_by_auth_user_id,replacement_owner_auth_user_id,justification,state) values(p_client_account_id,p_target_auth_user_id,v_actor,p_replacement_owner_auth_user_id,btrim(p_justification),'requested') returning * into v_workflow;insert into public.client_account_offboarding_events(workflow_id,event_type,actor_type,actor_auth_user_id,stage) values(v_workflow.id,'requested','authenticated',v_actor,'database');if v_target_is_owner and not v_other_owner_exists then insert into public.client_account_offboarding_events(workflow_id,event_type,actor_type,actor_auth_user_id,stage) values(v_workflow.id,'replacement_owner_established','authenticated',v_actor,'database');end if;perform public.remove_client_account_membership(p_client_account_id,p_target_auth_user_id,'offboarding: '||btrim(p_justification));update public.client_account_offboarding_workflows set state='database_access_removed',updated_at=clock_timestamp(),last_error_stage=null,last_error_code=null where id=v_workflow.id;insert into public.client_account_offboarding_events(workflow_id,event_type,actor_type,actor_auth_user_id,stage) values(v_workflow.id,'database_access_removed','authenticated',v_actor,'database');return v_workflow.id;end;$$;
revoke all on function public.start_client_account_offboarding(uuid,uuid,uuid,text) from public,anon,authenticated,service_role;grant execute on function public.start_client_account_offboarding(uuid,uuid,uuid,text) to authenticated;

create function public.mark_client_offboarding_sessions_revoked(p_workflow_id uuid) returns boolean language plpgsql security definer set search_path='' as $$ declare v_workflow public.client_account_offboarding_workflows;begin select * into v_workflow from public.client_account_offboarding_workflows where id=p_workflow_id for update;if not found then raise exception 'offboarding workflow inexistente';end if;if v_workflow.state in ('sessions_revoked','completed') then return false;end if;if v_workflow.state<>'database_access_removed' then raise exception 'estado inválido para confirmar revogação de sessões: %',v_workflow.state;end if;if not public.vida_auth_user_exists(v_workflow.target_auth_user_id) then raise exception 'ordem inválida: auth.users já foi removido antes da confirmação de sessions_revoked';end if;if vida_internal.auth_user_has_sessions(v_workflow.target_auth_user_id) then raise exception 'ainda existem sessões ativas/persistidas para o usuário alvo';end if;update public.client_account_offboarding_workflows set state='sessions_revoked',updated_at=clock_timestamp(),last_error_stage=null,last_error_code=null where id=p_workflow_id;insert into public.client_account_offboarding_events(workflow_id,event_type,actor_type,actor_auth_user_id,stage) values(p_workflow_id,'sessions_revoked','backend_system',null,'revoke_sessions');return true;end;$$;
revoke all on function public.mark_client_offboarding_sessions_revoked(uuid) from public,anon,authenticated,service_role;grant execute on function public.mark_client_offboarding_sessions_revoked(uuid) to service_role;

create function public.mark_client_offboarding_user_deleted(p_workflow_id uuid) returns boolean language plpgsql security definer set search_path='' as $$ declare v_workflow public.client_account_offboarding_workflows;begin select * into v_workflow from public.client_account_offboarding_workflows where id=p_workflow_id for update;if not found then raise exception 'offboarding workflow inexistente';end if;if v_workflow.state='completed' then return false;end if;if v_workflow.state<>'sessions_revoked' then raise exception 'estado inválido para confirmar exclusão do usuário: %',v_workflow.state;end if;if public.vida_auth_user_exists(v_workflow.target_auth_user_id) then raise exception 'auth.users ainda contém o usuário alvo';end if;update public.client_account_offboarding_workflows set state='completed',updated_at=clock_timestamp(),completed_at=clock_timestamp(),last_error_stage=null,last_error_code=null where id=p_workflow_id;insert into public.client_account_offboarding_events(workflow_id,event_type,actor_type,actor_auth_user_id,stage) values(p_workflow_id,'completed','backend_system',null,'delete_user');return true;end;$$;
revoke all on function public.mark_client_offboarding_user_deleted(uuid) from public,anon,authenticated,service_role;grant execute on function public.mark_client_offboarding_user_deleted(uuid) to service_role;

create function public.record_client_offboarding_retryable_failure(p_workflow_id uuid,p_stage text,p_error_code text) returns void language plpgsql security definer set search_path='' as $$ declare v_state text;v_expected_stage text;begin if p_stage not in ('revoke_sessions','delete_user') then raise exception 'stage inválido: %',p_stage;end if;if p_error_code is null or btrim(p_error_code)='' then raise exception 'error_code é obrigatório';end if;select state into v_state from public.client_account_offboarding_workflows where id=p_workflow_id for update;if not found then raise exception 'offboarding workflow inexistente';end if;if v_state='completed' then raise exception 'workflow já concluído';end if;v_expected_stage:=case v_state when 'database_access_removed' then 'revoke_sessions' when 'sessions_revoked' then 'delete_user' else null end;if v_expected_stage is distinct from p_stage then raise exception 'stage % incompatível com state %',p_stage,v_state;end if;update public.client_account_offboarding_workflows set retry_count=retry_count+1,last_error_stage=p_stage,last_error_code=left(btrim(p_error_code),200),updated_at=clock_timestamp() where id=p_workflow_id;insert into public.client_account_offboarding_events(workflow_id,event_type,actor_type,actor_auth_user_id,stage,detail_code) values(p_workflow_id,'retryable_failure','backend_system',null,p_stage,left(btrim(p_error_code),200));end;$$;
revoke all on function public.record_client_offboarding_retryable_failure(uuid,text,text) from public,anon,authenticated,service_role;grant execute on function public.record_client_offboarding_retryable_failure(uuid,text,text) to service_role;

alter table public.client_account_offboarding_workflows owner to vida_identity_owner;
alter table public.client_account_offboarding_events owner to vida_identity_owner;
alter function public.start_client_account_offboarding(uuid,uuid,uuid,text) owner to vida_identity_owner;
alter function public.mark_client_offboarding_sessions_revoked(uuid) owner to vida_identity_owner;
alter function public.mark_client_offboarding_user_deleted(uuid) owner to vida_identity_owner;
alter function public.record_client_offboarding_retryable_failure(uuid,text,text) owner to vida_identity_owner;

revoke create on schema public from vida_identity_owner;
grant vida_identity_owner to postgres with inherit false, set true;
commit;